INSERT INTO recipes (id, title, source, servings, serving_size, prep_minutes, cook_minutes, total_minutes, photos, tags, ingredients, steps, notes, rating, times_made, created_at, updated_at) VALUES ('1', 'Corn pudding', 'My recipe', 8, '1 square', 20, 55, 75, '[{"id":"s1000","src":"/photos/corn.jpg"}]'::jsonb, ARRAY['side', 'dessert', 'holiday']::text[], '[{"id":"s1001","kind":"header","amount":"","unit":"","name":"For the pudding","note":""},{"id":"s1002","amount":"6","unit":"cups","name":"fresh corn kernels","note":"from about 8 ears, or frozen and thawed","raw":"6 cups fresh corn kernels, from about 8 ears, or frozen and thawed"},{"id":"s1003","amount":"6","unit":"","name":"large eggs","note":"at room temperature","raw":"6 large eggs, at room temperature"},{"id":"s1004","amount":"2","unit":"cups","name":"heavy cream","note":"","raw":"2 cups heavy cream"},{"id":"s1005","amount":"1/2","unit":"cup","name":"whole milk","note":"","raw":"1/2 cup whole milk"},{"id":"s1006","amount":"1/2","unit":"cup","name":"unsalted butter","note":"melted and cooled, plus more for the dish","raw":"1/2 cup unsalted butter, melted and cooled, plus more for the dish"},{"id":"s1007","amount":"1/4","unit":"cup","name":"sugar","note":"","raw":"1/4 cup sugar"},{"id":"s1008","amount":"3","unit":"tbsp","name":"all-purpose flour","note":"","raw":"3 tbsp all-purpose flour"},{"id":"s1009","amount":"2","unit":"tsp","name":"baking powder","note":"","raw":"2 tsp baking powder"},{"id":"s1010","amount":"1-2","unit":"tsp","name":"kosher salt","note":"to taste","raw":"1-2 tsp kosher salt, to taste"},{"id":"s1011","amount":"1/4","unit":"tsp","name":"ground nutmeg","note":"","raw":"1/4 tsp ground nutmeg"},{"id":"s1012","kind":"header","amount":"","unit":"","name":"For the topping","note":""},{"id":"s1013","amount":"1/2","unit":"cup","name":"sharp cheddar","note":"finely grated","raw":"1/2 cup sharp cheddar, finely grated"},{"id":"s1014","amount":"2","unit":"tbsp","name":"brown sugar","note":"","raw":"2 tbsp brown sugar"},{"id":"s1015","amount":"2","unit":"","name":"green onions","note":"thinly sliced","raw":"2 green onions, thinly sliced"}]'::jsonb, '[{"id":"s1016","kind":"header","text":"Prep"},{"id":"s1017","text":"Heat the oven to 350°F with a rack in the middle. Butter a 9×13-inch baking dish generously, including the corners, so the edges release cleanly."},{"id":"s1018","text":"Put 2 cups of the corn in a blender with the milk and pulse until mostly smooth but still a little textured. This is what makes the pudding creamy rather than eggy."},{"id":"s1019","text":"In a large bowl, whisk the sugar, flour, baking powder, salt and nutmeg until there are no lumps of flour left."},{"id":"s1020","kind":"header","text":"Bake"},{"id":"s1021","text":"Whisk the eggs into the dry mixture one at a time, then whisk in the cream, the blended corn and the melted butter until smooth."},{"id":"s1022","text":"Fold in the remaining whole kernels and pour everything into the dish. Tap the dish on the counter a couple of times to settle it."},{"id":"s1023","text":"Bake 40 minutes, until the edges are set and the center still jiggles slightly. Scatter the cheddar and brown sugar over the top and bake 10 to 15 minutes more, until golden."},{"id":"s1024","text":"Let it rest 10 minutes before cutting so it firms up. Sprinkle with the green onions just before serving."}]'::jsonb, 'Halve the sugar if the corn is very sweet. It can be baked a day ahead and reheated, covered, at 325°F for 20 minutes. Freezes well for a month.', 5, 3, '2026-11-10', '2026-11-10') ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, title, source, servings, serving_size, prep_minutes, cook_minutes, total_minutes, photos, tags, ingredients, steps, notes, rating, times_made, created_at, updated_at) VALUES ('2', 'Middle Eastern Chicken Kebabs', 'onceuponachef.com', 4, '2 skewers', 20, 15, 35, '[{"id":"s1025","src":"/photos/kebabs.jpg"}]'::jsonb, ARRAY['dinner']::text[], '[{"id":"s1026","kind":"header","amount":"","unit":"","name":"Marinade","note":""},{"id":"s1027","amount":"1","unit":"cup","name":"plain whole milk Greek yogurt","note":"","raw":"1 cup plain whole milk Greek yogurt"},{"id":"s1028","amount":"1/4","unit":"cup","name":"olive oil","note":"","raw":"1/4 cup olive oil"},{"id":"s1029","amount":"2","unit":"tbsp","name":"lemon juice","note":"from about 1 lemon","raw":"2 tbsp lemon juice, from about 1 lemon"},{"id":"s1030","amount":"1","unit":"tsp","name":"lemon zest","note":"","raw":"1 tsp lemon zest"},{"id":"s1031","amount":"4","unit":"cloves","name":"garlic","note":"minced","raw":"4 cloves garlic, minced"},{"id":"s1032","amount":"2","unit":"tsp","name":"smoked paprika","note":"","raw":"2 tsp smoked paprika"},{"id":"s1033","amount":"1 1/2","unit":"tsp","name":"ground cumin","note":"","raw":"1 1/2 tsp ground cumin"},{"id":"s1034","amount":"1","unit":"tsp","name":"ground coriander","note":"","raw":"1 tsp ground coriander"},{"id":"s1035","amount":"1/2","unit":"tsp","name":"ground cinnamon","note":"","raw":"1/2 tsp ground cinnamon"},{"id":"s1036","amount":"1/2-1","unit":"tsp","name":"crushed red pepper flakes","note":"reduce if you don’t like heat","raw":"1/2-1 tsp crushed red pepper flakes, reduce if you don’t like heat"},{"id":"s1037","amount":"1 1/2","unit":"tsp","name":"kosher salt","note":"","raw":"1 1/2 tsp kosher salt"},{"id":"s1038","amount":"1/2","unit":"tsp","name":"black pepper","note":"","raw":"1/2 tsp black pepper"},{"id":"s1039","kind":"header","amount":"","unit":"","name":"Kebabs","note":""},{"id":"s1040","amount":"2","unit":"lb","name":"boneless chicken thighs","note":"cut into 1½-inch pieces","raw":"2 lb boneless chicken thighs, cut into 1½-inch pieces"},{"id":"s1041","amount":"1","unit":"large","name":"red onion","note":"cut into wedges","raw":"1 large red onion, cut into wedges"},{"id":"s1042","amount":"2","unit":"","name":"bell peppers","note":"cut into 1½-inch squares","raw":"2 bell peppers, cut into 1½-inch squares"},{"id":"s1043","amount":"8","unit":"","name":"wooden skewers","note":"soaked in water for 30 minutes","raw":"8 wooden skewers, soaked in water for 30 minutes"},{"id":"s1044","kind":"header","amount":"","unit":"","name":"To serve","note":""},{"id":"s1045","amount":"4","unit":"","name":"warm pitas","note":"","raw":"4 warm pitas"},{"id":"s1046","amount":"1/2","unit":"cup","name":"tahini sauce","note":"","raw":"1/2 cup tahini sauce"},{"id":"s1047","amount":"1/4","unit":"cup","name":"fresh parsley","note":"chopped","raw":"1/4 cup fresh parsley, chopped"},{"id":"s1048","amount":"1","unit":"","name":"lemon","note":"cut into wedges","raw":"1 lemon, cut into wedges"}]'::jsonb, '[{"id":"s1049","kind":"header","text":"Marinate"},{"id":"s1050","text":"In a large bowl, whisk together the yogurt, olive oil, lemon juice and zest, garlic, paprika, cumin, coriander, cinnamon, red pepper flakes, salt and pepper until smooth."},{"id":"s1051","text":"Add the chicken and turn it with your hands until every piece is coated. Cover the bowl and refrigerate for at least 8 hours, or overnight. The yogurt tenderizes the meat, so don’t skip the long marinade."},{"id":"s1052","kind":"header","text":"Grill"},{"id":"s1053","text":"Take the chicken out of the fridge 30 minutes before cooking. Heat the grill to medium-high and oil the grates well with a folded paper towel dipped in oil."},{"id":"s1054","text":"Thread the chicken onto the skewers, alternating with the onion and pepper. Leave a little space between pieces so they cook evenly, and wipe off any thick clumps of marinade."},{"id":"s1055","text":"Grill 10 to 15 minutes, turning every few minutes, until the chicken is charred in spots and reaches 165°F inside. Move the skewers to a cooler part of the grill if they flare up."},{"id":"s1056","text":"Rest the kebabs on a platter for 5 minutes. Serve with warm pitas, tahini sauce, parsley and lemon wedges."}]'::jsonb, 'Thighs stay juicier than breasts here. In winter, broil them on a foil-lined sheet pan about 4 inches from the heat, 6 to 8 minutes per side.', 5, 2, '2026-10-02', '2026-10-02') ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, title, source, servings, serving_size, prep_minutes, cook_minutes, total_minutes, photos, tags, ingredients, steps, notes, rating, times_made, created_at, updated_at) VALUES ('3', 'Italian Turkey Zucchini Meatballs', 'My recipe', 6, '4 meatballs', 15, 25, 40, '[{"id":"s1057","src":"/photos/meatballs.jpg"}]'::jsonb, ARRAY['dinner']::text[], '[{"id":"s1058","kind":"header","amount":"","unit":"","name":"Meatballs","note":""},{"id":"s1059","amount":"1 1/2","unit":"lb","name":"ground turkey","note":"93% lean","raw":"1 1/2 lb ground turkey, 93% lean"},{"id":"s1060","amount":"1","unit":"medium","name":"zucchini","note":"grated and squeezed dry in a towel","raw":"1 medium zucchini, grated and squeezed dry in a towel"},{"id":"s1061","amount":"1/2","unit":"cup","name":"panko breadcrumbs","note":"","raw":"1/2 cup panko breadcrumbs"},{"id":"s1062","amount":"1/3","unit":"cup","name":"parmesan","note":"finely grated, plus more to serve","raw":"1/3 cup parmesan, finely grated, plus more to serve"},{"id":"s1063","amount":"1","unit":"","name":"large egg","note":"","raw":"1 large egg"},{"id":"s1064","amount":"3","unit":"cloves","name":"garlic","note":"grated","raw":"3 cloves garlic, grated"},{"id":"s1065","amount":"2","unit":"tbsp","name":"fresh basil","note":"chopped","raw":"2 tbsp fresh basil, chopped"},{"id":"s1066","amount":"1","unit":"tsp","name":"dried oregano","note":"","raw":"1 tsp dried oregano"},{"id":"s1067","amount":"1/2-1","unit":"tsp","name":"red pepper flakes","note":"optional","raw":"1/2-1 tsp red pepper flakes, optional"},{"id":"s1068","amount":"1","unit":"tsp","name":"kosher salt","note":"","raw":"1 tsp kosher salt"},{"id":"s1069","kind":"header","amount":"","unit":"","name":"Sauce","note":""},{"id":"s1070","amount":"1","unit":"jar (24 oz)","name":"marinara sauce","note":"","raw":"1 jar (24 oz) marinara sauce"},{"id":"s1071","amount":"1","unit":"tbsp","name":"olive oil","note":"","raw":"1 tbsp olive oil"},{"id":"s1072","amount":"","unit":"","name":"fresh basil leaves","note":"to serve","raw":"fresh basil leaves, to serve"}]'::jsonb, '[{"id":"s1073","text":"Heat the oven to 400°F and line a sheet pan with parchment. Brush the parchment lightly with olive oil."},{"id":"s1074","text":"Wrap the grated zucchini in a clean kitchen towel and wring it out over the sink until no more water drips out. Wet zucchini makes the meatballs fall apart."},{"id":"s1075","text":"In a large bowl, combine the turkey, zucchini, panko, parmesan, egg, garlic, basil, oregano, pepper flakes and salt. Mix gently with your hands just until combined; overworking makes them tough."},{"id":"s1076","text":"Roll into about 24 meatballs the size of a golf ball, wetting your hands so the mixture doesn’t stick, and space them out on the pan."},{"id":"s1077","text":"Bake 18 to 20 minutes, until lightly browned and cooked through."},{"id":"s1078","text":"Warm the marinara in a wide pan, add the meatballs and simmer 5 minutes, spooning the sauce over them. Serve with extra parmesan and basil."}]'::jsonb, 'Good over polenta or spaghetti squash. The baked meatballs freeze well without the sauce.', 4, 1, '2026-09-14', '2026-09-14') ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, title, source, servings, serving_size, prep_minutes, cook_minutes, total_minutes, photos, tags, ingredients, steps, notes, rating, times_made, created_at, updated_at) VALUES ('4', 'Pulled Beef with Parsnip Purée', 'My recipe', 6, '', 30, 180, 210, '[{"id":"s1079","src":"/photos/pulled-beef.jpg"}]'::jsonb, ARRAY['dinner']::text[], '[{"id":"s1080","kind":"header","amount":"","unit":"","name":"Beef","note":""},{"id":"s1081","amount":"3","unit":"lb","name":"boneless chuck roast","note":"cut into 3 large pieces","raw":"3 lb boneless chuck roast, cut into 3 large pieces"},{"id":"s1082","amount":"2","unit":"tsp","name":"kosher salt","note":"","raw":"2 tsp kosher salt"},{"id":"s1083","amount":"2","unit":"tbsp","name":"olive oil","note":"","raw":"2 tbsp olive oil"},{"id":"s1084","amount":"1","unit":"large","name":"onion","note":"sliced","raw":"1 large onion, sliced"},{"id":"s1085","amount":"4","unit":"cloves","name":"garlic","note":"smashed","raw":"4 cloves garlic, smashed"},{"id":"s1086","amount":"2","unit":"tbsp","name":"tomato paste","note":"","raw":"2 tbsp tomato paste"},{"id":"s1087","amount":"1","unit":"cup","name":"dry red wine","note":"","raw":"1 cup dry red wine"},{"id":"s1088","amount":"2","unit":"cups","name":"beef broth","note":"","raw":"2 cups beef broth"},{"id":"s1089","amount":"3","unit":"sprigs","name":"fresh thyme","note":"","raw":"3 sprigs fresh thyme"},{"id":"s1090","amount":"2","unit":"","name":"bay leaves","note":"","raw":"2 bay leaves"},{"id":"s1091","kind":"header","amount":"","unit":"","name":"Parsnip purée","note":""},{"id":"s1092","amount":"2","unit":"lb","name":"parsnips","note":"peeled and cut into chunks","raw":"2 lb parsnips, peeled and cut into chunks"},{"id":"s1093","amount":"1","unit":"cup","name":"whole milk","note":"","raw":"1 cup whole milk"},{"id":"s1094","amount":"3","unit":"tbsp","name":"butter","note":"","raw":"3 tbsp butter"},{"id":"s1095","amount":"","unit":"","name":"salt and white pepper","note":"to taste","raw":"salt and white pepper, to taste"}]'::jsonb, '[{"id":"s1096","kind":"header","text":"Braise"},{"id":"s1097","text":"Heat the oven to 300°F. Pat the beef dry and season it all over with the salt."},{"id":"s1098","text":"Heat the oil in a Dutch oven over medium-high heat and brown the beef well on all sides, about 10 minutes. Move it to a plate."},{"id":"s1099","text":"Lower the heat to medium, add the onion and cook until soft, about 6 minutes. Stir in the garlic and tomato paste and cook 1 minute more."},{"id":"s1100","text":"Pour in the wine and scrape up the browned bits, then add the broth, thyme and bay leaves. Return the beef, cover and braise in the oven for 3 hours, until it pulls apart easily."},{"id":"s1101","kind":"header","text":"Purée and serve"},{"id":"s1102","text":"About 30 minutes before the beef is done, simmer the parsnips in the milk with a pinch of salt, covered, until very tender, 20 to 25 minutes."},{"id":"s1103","text":"Blend the parsnips with their milk and the butter until silky. Season with salt and white pepper."},{"id":"s1104","text":"Shred the beef with two forks and stir it into the reduced braising liquid. Spoon over the purée."}]'::jsonb, 'Even better the next day. Skim the fat off the chilled braising liquid before reheating.', 4, 1, '2026-08-21', '2026-08-21') ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, title, source, servings, serving_size, prep_minutes, cook_minutes, total_minutes, photos, tags, ingredients, steps, notes, rating, times_made, created_at, updated_at) VALUES ('5', 'Mustard Dill Chicken Thighs', 'sepcooks.com', 4, '', 10, 25, 35, '[{"id":"s1105","src":"/photos/mustard-chicken.jpg"}]'::jsonb, ARRAY['dinner', 'quick']::text[], '[{"id":"s1106","amount":"2","unit":"lb","name":"boneless chicken thighs","note":"","raw":"2 lb boneless chicken thighs"},{"id":"s1107","amount":"3","unit":"tbsp","name":"Dijon mustard","note":"","raw":"3 tbsp Dijon mustard"},{"id":"s1108","amount":"1","unit":"tbsp","name":"whole-grain mustard","note":"","raw":"1 tbsp whole-grain mustard"},{"id":"s1109","amount":"2","unit":"tbsp","name":"olive oil","note":"","raw":"2 tbsp olive oil"},{"id":"s1110","amount":"1","unit":"tbsp","name":"honey","note":"","raw":"1 tbsp honey"},{"id":"s1111","amount":"2","unit":"cloves","name":"garlic","note":"grated","raw":"2 cloves garlic, grated"},{"id":"s1112","amount":"1-2","unit":"tbsp","name":"fresh dill","note":"chopped, plus more to serve","raw":"1-2 tbsp fresh dill, chopped, plus more to serve"},{"id":"s1113","amount":"1","unit":"tsp","name":"kosher salt","note":"","raw":"1 tsp kosher salt"},{"id":"s1114","amount":"1/2","unit":"tsp","name":"black pepper","note":"","raw":"1/2 tsp black pepper"},{"id":"s1115","amount":"1","unit":"","name":"lemon","note":"halved","raw":"1 lemon, halved"}]'::jsonb, '[{"id":"s1116","text":"Heat the oven to 425°F. Pat the chicken dry with paper towels so the glaze sticks."},{"id":"s1117","text":"In a large bowl, stir together both mustards, the olive oil, honey, garlic, dill, salt and pepper."},{"id":"s1118","text":"Toss the chicken in the mustard mixture and arrange it in a single layer in a baking dish, smooth side up. Nestle the lemon halves in the dish, cut side up."},{"id":"s1119","text":"Roast 22 to 25 minutes, until the edges are browned and the chicken reaches 175°F inside."},{"id":"s1120","text":"Squeeze the roasted lemon over the chicken, spoon the pan juices on top and scatter with more dill."}]'::jsonb, '', 0, 0, '2026-07-30', '2026-07-30') ON CONFLICT (id) DO NOTHING;
